// Widths: Y 7 bits, z 7 bits (two's complement), from the exhaustive ranges over n = 0 .. 256.

module cordic_iter_r2_fo4_m5g2 (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        start,
  input  wire [8:0]  n,
  output reg         busy,
  output reg         done,
  output wire [4:0]  y
);
  // angle: Z = (n*C + 2^(P-1)) >> P (constant multiplier)
  wire [20:0] a_prod = {12'd0, n} * 21'd4096;
  wire [20:0] a_sum  = a_prod + 21'd32768;
  wire [4:0] Z      = a_sum[20:16];
  // range reduction: Z < L = 44 for every input, so q = 0 and r = Z
  wire [4:0] r_c = Z;

