    (cnt == 3'd1) ? 3'd2 :
    (cnt == 3'd2) ? 3'd3 :
    (cnt == 3'd3) ? 3'd4 :
    3'd4;
  assign a_cur =
    (cnt == 3'd0) ? 7'd35 :
    (cnt == 3'd1) ? 7'd16 :
    (cnt == 3'd2) ? 7'd8 :
    (cnt == 3'd3) ? 7'd4 :
    7'd4;

  // one rotation: d = +1 if z >= 0; Y += d (Y >> i); z -= d A_i
  wire        d      = ~zr[6];
  wire [6:0] ysh    = Yr >> i_cur;
  wire [6:0] y_next = Yr + (ysh ^ {7{~d}}) + {6'd0, ~d};
  wire [6:0] z_next = zr + (a_cur ^ {7{d}}) + {6'd0, d};
  wire [6:0] z_ifull = 7'd0 - {2'd0, r_c};   // -r
  wire [6:0] z_init = z_ifull[6:0];

  // control: start is accepted when busy = 0; busy covers the iterations; done pulses for one cycle
  wire last = (cnt == 3'd4);
  always @(posedge clk) begin
    if (!rst_n) begin
      busy <= 1'b0;
      done <= 1'b0;
    end else begin
      done <= busy & last;
      if (!busy) busy <= start;
      else if (last) busy <= 1'b0;
    end
  end

  always @(posedge clk) begin
    if (!busy) begin
      if (start) begin
        Yr  <= 7'd77;
        zr  <= z_init;
        cnt <= 3'd0;
      end
    end else begin
      Yr  <= y_next;
      zr  <= z_next;
      cnt <= cnt + 3'd1;
    end
