  wire [7:0] o_yx = {Yr, 1'b0};
  wire [5:0] o_t = o_yx[7:2];
  wire [6:0] o_tp1 = {1'b0, o_t} + 7'd1;
  wire [5:0] o_yr  = o_tp1[6:1];
  wire [4:0] y_c = ((o_yr > 6'd16) ? 5'd16 : o_yr[4:0]);

  assign y = y_c;
endmodule
